// Copies the in-VM plugin shim (server/services/plugins/shim/mcpjam-plugin-shim.mjs)
// into a generated TS const, because nothing in the server graph IMPORTS the
// .mjs — it is uploaded into a sandbox and executed there. Without this step the
// bundler never walks to it and the published package would not contain it.
// Mirrors the `bundle:sandbox-proxies` pattern (generated .ts consumed at
// runtime, wired into `pretest` + `build`). Auto-generated output is gitignored.
//
// The emitted version is the shim's own content hash, so the backend's
// `shim_outdated` staleness check fires exactly when this file changes — there
// is no hand-maintained version to forget to bump.
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));

const shimPath = join(
  __dirname,
  "../server/services/plugins/shim/mcpjam-plugin-shim.mjs",
);
const outputTsPath = join(
  __dirname,
  "../server/services/plugins/shim/PluginShim.bundled.ts",
);

try {
  const source = readFileSync(shimPath, "utf-8");
  const version = createHash("sha256")
    .update(source, "utf8")
    .digest("hex")
    .slice(0, 16);

  const outputContent = `// This file is auto-generated by scripts/bundle-plugin-shim.mjs
// Do not edit directly - modify server/services/plugins/shim/mcpjam-plugin-shim.mjs instead

export const PLUGIN_SHIM_SOURCE = ${JSON.stringify(source)};

/** sha256 of the source above, truncated. Changes whenever the shim changes. */
export const PLUGIN_SHIM_VERSION = ${JSON.stringify(version)};
`;

  writeFileSync(outputTsPath, outputContent);
  process.stdout.write(
    `Bundled plugin VM shim (${(source.length / 1024).toFixed(
      1,
    )} KiB, version ${version})\n`,
  );
} catch (error) {
  process.stderr.write(
    `Failed to bundle plugin VM shim: ${
      error instanceof Error ? error.message : String(error)
    }\n`,
  );
  process.exit(1);
}
